package org.usbworkbench;
import java.io.*;import java.nio.charset.*;import java.security.*;import java.util.*;
/** Original bounded optical-image model. Data is streamed from seekable source, never cached whole. */
public final class OpticalImage {
 public interface Source extends Closeable {long size()throws IOException;void read(long offset,byte[] data,int at,int count)throws IOException;}
 public interface Sink extends ZipTools.Sink {InputStream reopen(String path)throws IOException;}
 public static final int BLOCK=2048,MAX_ENTRIES=50000,MAX_DEPTH=32;
 public static final long MAX_METADATA=64L*1024*1024,MAX_DIRECTORY=16L*1024*1024;
 public static final class Range {public final long offset,length;public final byte[] inline;public Range(long offset,long length){this(offset,length,null);}public Range(byte[] bytes){this(0,bytes.length,bytes.clone());}private Range(long o,long n,byte[] b){offset=o;length=n;inline=b;}}
 public static final class Entry {public final String path;public final boolean directory;public final long size;public final List<Range> ranges;public Entry(String path,boolean dir,long size,List<Range> ranges)throws IOException{if(size<0||size>(1L<<44))throw new IOException("IMAGE_BOUNDS");this.path=path;directory=dir;this.size=size;this.ranges=Collections.unmodifiableList(new ArrayList<>(ranges));long sum=0;for(Range r:ranges){if(r.length<0||r.length>Long.MAX_VALUE-sum)throw new IOException("IMAGE_BOUNDS");sum+=r.length;}if(sum<size)throw new IOException("IMAGE_BOUNDS");}}
 public static final class Manifest {public final String filesystem;public final List<Entry> entries=new ArrayList<>();private final Map<String,Entry> names=new HashMap<>();public long totalBytes;Manifest(String fs){filesystem=fs;}void add(Entry entry)throws IOException{if(entries.size()>=MAX_ENTRIES)throw new IOException("IMAGE_LIMIT");String key=entry.path.toLowerCase(Locale.ROOT);if(names.containsKey(key))throw new IOException("IMAGE_DUPLICATE");if(!entry.directory){if(entry.size>(1L<<44)-totalBytes)throw new IOException("IMAGE_LIMIT");totalBytes+=entry.size;}names.put(key,entry);entries.add(entry);}public Entry find(String path){return names.get(path.toLowerCase(Locale.ROOT));}
  public String windowsPreflight()throws IOException{return windowsPreflight(false);}
  private String windowsPreflight(boolean split)throws IOException{if(find("sources/boot.wim")==null||find("setup.exe")==null||(find("sources/install.wim")==null&&find("sources/install.esd")==null&&find("sources/install.swm")==null))throw new IOException("NOT_WINDOWS_ISO");String arch=find("efi/boot/bootx64.efi")!=null?"x64":find("efi/boot/bootaa64.efi")!=null?"ARM64":find("efi/boot/bootia32.efi")!=null?"x86":"";if(arch.isEmpty())throw new IOException("WINDOWS_NO_EFI");for(Entry e:entries)if(!e.directory&&e.size>0xffffffffL&&!(split&&e.path.equalsIgnoreCase("sources/install.wim")))throw new IOException(e.path.equalsIgnoreCase("sources/install.wim")?"WIM_SPLIT_REQUIRED":"FAT32_FILE_LIMIT");return arch;}
  public String windowsPreflight(Source source)throws IOException{return windowsPreflight(source,false);}
  public String windowsPreflight(Source source,boolean split)throws IOException{String arch=windowsPreflight(split);
   for(Entry e:entries)for(String component:e.path.split("/")){String upper=component.toUpperCase(Locale.ROOT);if(component.matches(".*[<>:\"|?*].*")||component.endsWith(".")||component.endsWith(" ")||upper.matches("(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(\\..*)?"))throw new IOException("WINDOWS_FILE_NAME");}
   int sets=(find("sources/install.wim")!=null?1:0)+(find("sources/install.esd")!=null?1:0)+(find("sources/install.swm")!=null?1:0);if(sets!=1)throw new IOException("WINDOWS_IMAGE_SET");wimHeader(source,required("sources/boot.wim"),1,1,null,true);
   String installer=find("sources/install.wim")!=null?"sources/install.wim":find("sources/install.esd")!=null?"sources/install.esd":"sources/install.swm";Entry first=required(installer);byte[] header=wimHeader(source,first,1,-1,null,true);int parts=u16(header,42);if(!installer.endsWith(".swm")&&parts!=1)throw new IOException("WINDOWS_IMAGE_SET");if(parts<1||parts>1024)throw new IOException("WINDOWS_IMAGE_SET");byte[] guid=Arrays.copyOfRange(header,24,40);for(int i=2;i<=parts;i++)wimHeader(source,required("sources/install"+i+".swm"),i,parts,guid,false);
   for(String file:new String[]{"efi/boot/bootx64.efi","efi/boot/bootaa64.efi","efi/boot/bootia32.efi"})if(find(file)!=null)efiHeader(source,required(file),file.endsWith("x64.efi")?0x8664:file.endsWith("aa64.efi")?0xaa64:0x14c);return arch;
  }
  private Entry required(String path)throws IOException{Entry e=find(path);if(e==null||e.directory)throw new IOException("WINDOWS_IMAGE_SET");return e;}
  private static byte[] wimHeader(Source source,Entry entry,int part,int total,byte[] guid,boolean first)throws IOException{if(entry.size<208)throw new IOException("WINDOWS_WIM_HEADER");byte[] b=new byte[208];read(source,entry,0,b,0,b.length);if(!Arrays.equals(Arrays.copyOf(b,8),new byte[]{77,83,87,73,77,0,0,0})||u32(b,8)<208||u32(b,8)>4096||u32(b,8)>entry.size||u16(b,40)!=part||total>=0&&u16(b,42)!=total||first&&u32(b,44)==0||guid!=null&&!Arrays.equals(guid,Arrays.copyOfRange(b,24,40)))throw new IOException("WINDOWS_WIM_HEADER");return b;}
  private static void efiHeader(Source source,Entry entry,int machine)throws IOException{if(entry.size<128)throw new IOException("WINDOWS_EFI_HEADER");byte[] b=new byte[64];read(source,entry,0,b,0,b.length);long offset=u32(b,60);if(b[0]!='M'||b[1]!='Z'||offset>entry.size-94)throw new IOException("WINDOWS_EFI_HEADER");byte[] pe=new byte[94];read(source,entry,offset,pe,0,pe.length);int magic=u16(pe,24);if(pe[0]!='P'||pe[1]!='E'||pe[2]!=0||pe[3]!=0||u16(pe,4)!=machine||u16(pe,20)<70||magic!=(machine==0x14c?0x10b:0x20b)||u16(pe,92)!=10)throw new IOException("WINDOWS_EFI_HEADER");}

 }
 static final class Budget {long metadata;void metadata(long n)throws IOException{if(n<0||n>MAX_METADATA-metadata)throw new IOException("IMAGE_LIMIT");metadata+=n;}}
 static byte[] bytes(Source source,long offset,int n)throws IOException{long size=source.size();if(offset<0||n<0||offset>size||n>size-offset)throw new IOException("IMAGE_BOUNDS");byte[] b=new byte[n];source.read(offset,b,0,n);return b;}
 static long u32(byte[] b,int at){return (b[at]&255L)|((b[at+1]&255L)<<8)|((b[at+2]&255L)<<16)|((b[at+3]&255L)<<24);}static int u16(byte[] b,int at){return (b[at]&255)|((b[at+1]&255)<<8);}static long u64(byte[] b,int at)throws IOException{long value=0;for(int i=0;i<8;i++)value|=(b[at+i]&255L)<<(i*8);if(value<0)throw new IOException("IMAGE_BOUNDS");return value;}
 static String safe(String parent,String name)throws IOException{if(name.isEmpty()||name.equals(".")||name.equals("..")||name.contains("/")||name.contains("\\"))throw new IOException("IMAGE_PATH");String result=parent.isEmpty()?name:parent+"/"+name;try{ZipTools.safePath(result);}catch(IOException e){throw new IOException("IMAGE_PATH");}if(result.split("/").length>MAX_DEPTH)throw new IOException("IMAGE_LIMIT");return result;}
 static String decode(byte[] b,int off,int count,Charset charset)throws IOException{try{return charset.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(b,off,count)).toString();}catch(CharacterCodingException e){throw new IOException("IMAGE_NAME");}}
 public static Manifest scan(Source source,DiskTools.Progress p)throws IOException{boolean udf=false;for(int i=16;i<64&&((long)i+1)*BLOCK<=source.size();i++){byte[] b=bytes(source,(long)i*BLOCK,7);String id=new String(b,1,5,StandardCharsets.US_ASCII);if(id.equals("NSR02")||id.equals("NSR03"))udf=true;}return udf?UdfImage.scan(source,p):Iso9660Image.scan(source,p);}
 public static void read(Source source,Entry entry,long offset,byte[] out,int at,int count)throws IOException{if(offset<0||count<0||offset>entry.size||count>entry.size-offset)throw new IOException("IMAGE_BOUNDS");long base=0;int done=0;for(Range range:entry.ranges){long valid=Math.min(range.length,Math.max(0,entry.size-base));if(offset>=base+valid){base+=valid;continue;}long skip=offset-base;int n=(int)Math.min(count-done,valid-skip);if(range.inline!=null)System.arraycopy(range.inline,(int)skip,out,at+done,n);else if(range.offset<0)Arrays.fill(out,at+done,at+done+n,(byte)0);else{long absolute=range.offset+skip;if(absolute<0||absolute>source.size()||n>source.size()-absolute)throw new IOException("IMAGE_BOUNDS");source.read(absolute,out,at+done,n);}done+=n;offset+=n;base+=valid;if(done==count)return;}if(done!=count)throw new IOException("IMAGE_BOUNDS");}
 public static void extract(Source source,Manifest manifest,Sink sink,DiskTools.Progress p)throws IOException{byte[] b=new byte[65536];long complete=0;for(Entry entry:manifest.entries){p.update(complete*2,manifest.totalBytes*2);if(entry.directory){sink.directory(entry.path);continue;}int slash=entry.path.lastIndexOf('/');if(slash>0)sink.directory(entry.path.substring(0,slash));MessageDigest expected=sha();try(OutputStream out=sink.file(entry.path)){for(long done=0;done<entry.size;){int n=(int)Math.min(b.length,entry.size-done);p.update(complete*2+done,manifest.totalBytes*2);read(source,entry,done,b,0,n);out.write(b,0,n);expected.update(b,0,n);done+=n;}out.flush();}MessageDigest actual=sha();long verified=0;try(InputStream in=sink.reopen(entry.path)){int n;while((n=in.read(b))!=-1){if(n==0)throw new IOException("SOURCE_STALLED");if(n>entry.size-verified)throw new IOException("VERIFY_FAILED");p.update(complete*2+entry.size+verified,manifest.totalBytes*2);actual.update(b,0,n);verified+=n;}}if(verified!=entry.size||!MessageDigest.isEqual(expected.digest(),actual.digest()))throw new IOException("VERIFY_FAILED");complete+=entry.size;}p.update(manifest.totalBytes*2,manifest.totalBytes*2);}
 private static MessageDigest sha(){try{return MessageDigest.getInstance("SHA-256");}catch(NoSuchAlgorithmException e){throw new AssertionError(e);}}
}
